package com.anto426.uniapp.ui.document

import androidx.compose.ui.graphics.Color
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue

class DocumentMarkdownParserTest {
    @Test
    fun normalizeHandlesGitHubReleaseHtmlCommentsDetailsAndEntities() {
        val raw = """
            <!-- generated by release workflow -->
            <details><summary>Dettagli tecnici</summary>
            <p>Aggiornata l&rsquo;interfaccia &#8217;26.<br/>Vedi <a href="https://github.com/Anto426-Project/uniapp">repository</a>.</p>
            </details>
        """.trimIndent()

        val normalized = DocumentMarkdownParser.normalizeDocumentMarkdown(raw)
        assertFalse(normalized.contains("<!--"))
        assertTrue(normalized.contains("### Dettagli tecnici"))
        assertTrue(normalized.contains("l’interfaccia ’26."))
        assertTrue(normalized.contains("[repository](https://github.com/Anto426-Project/uniapp)"))
    }

    @Test
    fun splitMarkdownSectionsIgnoresHeadingsInsideFencedCodeAndCleansBoldTitles() {
        val md = """
            Introduzione breve.

            ## **Novità**
            - Primo elemento
            ```bash
            ## commento nel codice
            echo ok
            ```

            ## Correzione bug
            - Fix crash
        """.trimIndent()

        val sections = DocumentMarkdownParser.splitMarkdownSections(md)
        assertEquals(3, sections.size)
        assertEquals(null, sections[0].title)
        assertEquals("Introduzione breve.", sections[0].body)
        assertEquals("Novità", sections[1].title)
        assertTrue(sections[1].body.contains("## commento nel codice"))
        assertEquals("Correzione bug", sections[2].title)
    }

    @Test
    fun parseBlocksHandlesHeadingsAlertsIndentedListsTasksCodeAndTables() {
        val md = """
            #### Sottotitolo quarto livello

            > [!TIP]
            > Prima riga consiglio
            > Seconda riga consiglio

            - Voce principale
              - Sottovoce indentata
            - [x] Completato
            - [ ] Da fare

            ```kotlin
            val ok = true
            ```

            | Modulo | Stato |
            | --- | --- |
            | SDK | Locale |
        """.trimIndent()

        val blocks = DocumentMarkdownParser.parseMarkdownBlocks(md)
        assertEquals(MarkdownBlock.Heading(4, "Sottotitolo quarto livello"), blocks[0])
        assertEquals(
            MarkdownBlock.BlockQuote("Prima riga consiglio\nSeconda riga consiglio", MarkdownAlertKind.Tip),
            blocks[1],
        )
        assertEquals(MarkdownBlock.ListItem("•", "Voce principale", 0), blocks[2])
        assertEquals(MarkdownBlock.ListItem("◦", "Sottovoce indentata", 1), blocks[3])
        assertEquals(MarkdownBlock.TaskItem(true, "Completato", 0), blocks[4])
        assertEquals(MarkdownBlock.TaskItem(false, "Da fare", 0), blocks[5])
        assertEquals(MarkdownBlock.CodeBlock("kotlin", "val ok = true"), blocks[6])
        assertEquals(
            MarkdownBlock.TableBlock(listOf("Modulo", "Stato"), listOf(listOf("SDK", "Locale"))),
            blocks[7],
        )
    }

    @Test
    fun inlineParserHandlesAutoLinksMailtoUnderscoresAndSnakeCaseSafely() {
        val annotated = parseInlineMarkdown(
            text = "Vedi <https://unimol.it>, __forte__, _corsivo_, ~~vecchio~~, snake_case_id e [Email](mailto:test@example.com)",
            linkColor = Color.Blue,
        )

        val plain = annotated.text
        assertTrue(plain.contains("https://unimol.it"))
        assertFalse(plain.contains("<https://"))
        assertTrue(plain.contains("forte"))
        assertFalse(plain.contains("__"))
        assertTrue(plain.contains("corsivo"))
        assertTrue(plain.contains("vecchio"))
        assertFalse(plain.contains("~~"))
        assertTrue(plain.contains("snake_case_id"))
        assertTrue(plain.contains("Email"))
    }

    @Test
    fun denseLegalParagraphsReflowIntoReadableParagraphBlocks() {
        val denseLegalSection =
            "UniApp conserva credenziali, sessioni e copie locali dei dati attraverso l'archiviazione protetta. " +
                "I dati accademici restano isolati per account e profilo all'interno del dispositivo. " +
                "Su Android il sistema usa file cifrati con chiavi gestite dal Keystore di sistema. " +
                "La verifica biometrica resta delegata interamente al sistema operativo senza salvare impronte."

        val blocks = DocumentMarkdownParser.parseMarkdownBlocks(denseLegalSection)
        assertTrue(blocks.size >= 2)
        assertTrue(blocks.all { it is MarkdownBlock.Paragraph })
    }

    @Test
    fun changelogNormalizationCompactsGitHubPullAndCompareUrls() {
        val releaseNotes = """
            ## What's Changed
            * Migliorata la lettura delle notizie in https://github.com/Anto426-Project/uniapp/pull/42
            **Full Changelog**: https://github.com/Anto426-Project/uniapp/compare/v2.0.19...v2.0.20
        """.trimIndent()

        val normalized = DocumentMarkdownParser.normalizeDocumentMarkdown(releaseNotes)
        assertTrue(normalized.contains("[#42](https://github.com/Anto426-Project/uniapp/pull/42)"))
        assertTrue(normalized.contains("[v2.0.19...v2.0.20](https://github.com/Anto426-Project/uniapp/compare/v2.0.19...v2.0.20)"))
    }
}
